	ALTER TABLE [metrics].[AssetVersionConditionItem] CHECK CONSTRAINT [FK_MetricAssetVersionConditionItem_FieldType];
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAssetVersionConditionItem_IntersectType')
