if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAssetVersionConditionItem_MetricAssetVersionCondition')
begin
	ALTER TABLE [metrics].[AssetVersionConditionItem]  WITH CHECK ADD  CONSTRAINT [FK_MetricAssetVersionConditionItem_MetricAssetVersionCondition] FOREIGN KEY([AssetVersionConditionUid]) REFERENCES [metrics].[AssetVersionCondition] ([Uid]) ON DELETE CASCADE;
